0d2e3721122fd589711e56ba46e109d1e10fccd2.source:
static const PsgCmd *LastQueuedOrCommitted(u8 ch)
{
    u8 bit = (u8)(1u << ch);
    if ((s_psg_pending_mask & bit) && s_psg_pending[ch].valid) {
        return &s_psg_pending[ch];
    }
    if (s_psg_shadow[ch].valid) {
        return &s_psg_shadow[ch];
    }
    return 0;
}

b5f44993bee712a6d62ca8ce5ae09dff4f5b0de0.source:
static void CommitPendingShadows(void)
{
    u8 ch;
    if (!s_psg_commit_mask) {
        return;
    }
    for (ch = 0; ch < 4; ch++) {
        u8 bit = (u8)(1u << ch);
        if ((s_psg_commit_mask & bit) && s_psg_pending[ch].valid) {
            s_psg_shadow[ch] = s_psg_pending[ch];
            s_psg_shadow[ch].valid = 1;
            s_psg_pending_mask &= (u8)~bit;
        }
    }
    s_psg_commit_mask = 0;
}

dd9ffde0ade07ffb633f9b10f73df11735efa31f.source:
static void BufferReplayPending(void)
{
    static const u8 kOrder[4] = {3, 0, 1, 2};
    u8 i;
    for (i = 0; i < 4; i++) {
        u8 ch = kOrder[i];
        u8 bit = (u8)(1u << ch);
        if ((s_psg_pending_mask & bit) && !(s_psg_commit_mask & bit) && s_psg_pending[ch].valid) {
            if (BufferPushIfSpace(s_psg_pending[ch].b1, s_psg_pending[ch].b2, s_psg_pending[ch].b3)) {
                s_psg_commit_mask |= bit;
            }
        }
    }
}

8e310a32a3397457798f1da74876d9c27cb60912.source:
static u8 WaitBufferFree(void)
{
    if ((*(volatile u8 *)0x7003)) {
        s_sound_fault = 1;
        s_sound_drops++;
        return 0;
    }
    return 1;
}

2bf2360f929aa9166950da40afba2ea05e9e748b.source:
static u8 WaitBufferFreeSpin(u16 spin)
{
    while ((*(volatile u8 *)0x7003) && spin-- > 0) {
    }
    if ((*(volatile u8 *)0x7003)) {
        s_sound_fault = 1;
        s_sound_drops++;
        return 0;
    }
    return 1;
}

3fed13cb66e385e9e815f0d5dc4ac19126efa33a.source:
static void BufferPush(u8 b1, u8 b2, u8 b3)
{
    if (s_buf_count < 5) {
        u8 idx = (u8)(s_buf_count * 3);
        ngc_sound_staging[idx + 0] = b1;
        ngc_sound_staging[idx + 1] = b2;
        ngc_sound_staging[idx + 2] = b3;
        s_buf_count++;
    }
}

3c0ac38ba7544ceef6e5268740a1352ab1b1fdbd.source:
static u8 BufferPushIfSpace(u8 b1, u8 b2, u8 b3)
{
    if (s_buf_count < 5) {
        BufferPush(b1, b2, b3);
        return 1;
    }
    s_sound_fault = 1;
    s_sound_drops++;
    return 0;
}

438d8244bf7da47b3c007c92ced9578a86125197.source:
static int BufferPushIfChanged(u8 ch, const PsgCmd *cmd)
{
    const PsgCmd *last;
    u8 bit;
    if (!cmd || !cmd->valid) {
        return 0;
    }
    last = LastQueuedOrCommitted(ch);
    if (last &&
        last->b1 == cmd->b1 &&
        last->b2 == cmd->b2 &&
        last->b3 == cmd->b3) {
        return 0;
    }
    if (!BufferPushIfSpace(cmd->b1, cmd->b2, cmd->b3)) {
        return -1;
    }
    s_psg_pending[ch] = *cmd;
    s_psg_pending[ch].valid = 1;
    bit = (u8)(1u << ch);
    s_psg_pending_mask |= bit;
    s_psg_commit_mask |= bit;
    return 1;
}

dd4be2bef240a85412f56b13de46e71c7fe25c68.source:
static int BufferPushBytesIfChanged(u8 ch, u8 b1, u8 b2, u8 b3)
{
    PsgCmd cmd;
    cmd.valid = 1;
    cmd.b1 = b1;
    cmd.b2 = b2;
    cmd.b3 = b3;
    return BufferPushIfChanged(ch, &cmd);
}

f5a30074b42e0e0373df58baa75d2787862960e4.source:
static void BufferCommit(void)
{
    u8 i;
    u8 bytes;
    if (s_buf_count == 0) {
        return;
    }
    if (!WaitBufferFree()) {
        s_buf_count = 0;
        s_psg_commit_mask = 0;
        return;
    }
    bytes = (u8)(s_buf_count * 3);
    for (i = 0; i < bytes; i++) {
        ((volatile u8 *)0x7004)[i] = ngc_sound_staging[i];
    }
    (*(volatile u8 *)0x7003) = s_buf_count;
    s_buf_count = 0;
    CommitPendingShadows();
}

3bf7db092486cd3630e04c5ec390f53431bbf558.source:
static void BufferCommitBlocking(u16 spin)
{
    u8 i;
    u8 bytes;
    if (s_buf_count == 0) {
        return;
    }
    if (!WaitBufferFreeSpin(spin)) {
        s_buf_count = 0;
        s_psg_commit_mask = 0;
        return;
    }
    bytes = (u8)(s_buf_count * 3);
    for (i = 0; i < bytes; i++) {
        ((volatile u8 *)0x7004)[i] = ngc_sound_staging[i];
    }
    (*(volatile u8 *)0x7003) = s_buf_count;
    s_buf_count = 0;
    CommitPendingShadows();
}

