static void BgmVoice_ResetFx(BgmVoice *v)
{
    v->note_active = 0;
    v->note_idx = 0;
    v->gate_active = 0;
    v->gate_off_frame = 0;
    BgmVoice_ApplyInstrument(v, v->inst_id);
    v->macro_active = 0;
    v->macro_counter = 0;
    v->macro_step = 0;
    v->macro_pitch = 0;
    v->base_div = 1;
    v->tone_div = 1;
    v->pitch_index = 0;
    v->pitch_counter = v->env_speed;
    v->pitch_offset = 0;
    v->expression = 0;
    v->pitch_bend = 0;
    v->shadow_b1 = (u8)(v->attn_base | 0x0F);
    v->shadow_b2 = (u8)(v->attn_base | 0x0F);
    v->shadow_b3 = (u8)(v->attn_base | 0x0F);
}

