static void BgmVoice_Reset(BgmVoice *v)
{
    v->ptr = 0;
    v->start = 0;
    v->next_frame = 0;
    v->gate_off_frame = 0;
    v->inst_id = (v->freq_base == 0xE0 && s_bgm_instrument_count > 1) ? 1 : 0;
    BgmVoice_ResetFx(v);
    v->enabled = 0;
    v->shadow_b1 = (u8)(v->attn_base | 0x0F);
    v->shadow_b2 = (u8)(v->attn_base | 0x0F);
    v->shadow_b3 = (u8)(v->attn_base | 0x0F);
    v->loop = 0;
}

