a3060966ef8444a3173cb653220b8e7fa1ceee21.source:
static u16 BgmNoteToDiv(u8 note_idx)
{
    u8 idx;
    u8 lo;
    u8 hi;
    const u8 *table = s_bgm_note_table ? s_bgm_note_table : NOTE_TABLE;
    if (!table) {
        return 1;
    }
    if (note_idx == 0) {
        note_idx = 1;
    } else if (note_idx > 50 + 1) {
        note_idx = 50 + 1;
    }
    idx = (u8)(note_idx - 1);
    lo = table[idx * 2 + 0] & 0x0F;
    hi = table[idx * 2 + 1] & 0x3F;
    return (u16)(((u16)hi << 4) | (u16)lo);
}

78c6dca08414376700001529ac465f1fafdafe59.source:
static void BgmVoice_SetNote(BgmVoice *v, u8 note_idx)
{
    v->note_active = 1;
    v->note_idx = note_idx;
    if (v->adsr_on) {
        v->attn_cur = 15;
        v->adsr_phase = 1;
        v->adsr_counter = v->adsr_attack;
    } else {
        v->attn_cur = v->attn;
    }
    v->env_counter = v->env_speed;
    v->env_index = 0;
    v->pitch_index = 0;
    v->pitch_counter = v->env_speed;
    v->pitch_offset = 0;
    v->vib_delay_counter = v->vib_delay;
    v->vib_counter = v->vib_speed;
    v->vib_dir = 1;
    v->lfo_counter = v->lfo_rate;
    v->lfo_sign = 1;
    v->lfo_delta = 0;
    v->sweep_counter = v->sweep_speed;
    BgmVoice_MacroReset(v);
    if (v->mode == 0) {
        v->base_div = BgmNoteToDiv(note_idx);
        v->tone_div = v->base_div;
    } else {
        v->base_div = 1;
        v->tone_div = 1;
    }
}

bbfa5d36ee51fd5d5aadbd391d3b2e2b3ec46bc3.source:
static void BgmVoice_CommandFromState(BgmVoice *v, PsgCmd *cmd)
{
    if (!v->note_active) {
        cmd->valid = 0;
        return;
    }
    {
        u8 final_attn = v->attn_cur;
        if (v->lfo_attn_delta != 0) {
            s16 la = (s16)final_attn + (s16)v->lfo_attn_delta;
            if (la < 0) la = 0;
            if (la > 15) la = 15;
            final_attn = (u8)la;
        }
        if (v->expression > 0) {
            u8 ea = (u8)(final_attn + v->expression);
            if (ea > 15) ea = 15;
            final_attn = ea;
        }
        if (s_bgm_fade_attn > 0) {
            u8 fa = (u8)(final_attn + s_bgm_fade_attn);
            if (fa > 15) fa = 15;
            final_attn = fa;
        }
        if (s_bgm_master_attn > 0) {
            u8 ma = (u8)(final_attn + s_bgm_master_attn);
            if (ma > 15) ma = 15;
            final_attn = ma;
        }
        if (v->mode == 1) {
            PsgCmd ncmd;
            MakeNoiseCmdFromNote(v->note_idx, final_attn, &ncmd);
            v->shadow_b1 = ncmd.b1;
            v->shadow_b2 = ncmd.b2;
            v->shadow_b3 = ncmd.b3;
        } else {
            s16 vib_delta = 0;
            u16 div = v->tone_div;
            {
                s16 delta = 0;
                if (v->macro_pitch != 0) {
                    delta = (s16)(delta + v->macro_pitch);
                }
                if (v->pitch_bend != 0) {
                    delta = (s16)(delta + v->pitch_bend);
                }
                if (v->lfo_pitch_delta != 0) {
                    delta = (s16)(delta + v->lfo_pitch_delta);
                }
                if (delta != 0) {
                    s16 md = (s16)div + delta;
                    if (md < 1) md = 1;
                    if (md > 1023) md = 1023;
                    div = (u16)md;
                }
            }
            if (v->vib_on && v->vib_depth > 0 && v->vib_delay_counter == 0) {
                vib_delta = (s16)v->vib_depth * (s16)v->vib_dir;
            }
            if (vib_delta != 0) {
                s16 vd = (s16)div + vib_delta;
                if (vd < 1) vd = 1;
                if (vd > 1023) vd = 1023;
                div = (u16)vd;
            }
            v->shadow_b1 = (u8)(v->freq_base | (div & 0x0F));
            v->shadow_b2 = (u8)((div >> 4) & 0x3F);
            v->shadow_b3 = (u8)(v->attn_base | (final_attn & 0x0F));
        }
    }
    cmd->valid = 1;
    cmd->b1 = v->shadow_b1;
    cmd->b2 = v->shadow_b2;
    cmd->b3 = v->shadow_b3;
}

cda38686a5522d1ef651c30dd4023fd58c98209c.source:
static u16 BgmMulDiv100(u16 value, u8 percent)
{
    u16 q = (u16)(value / 100u);
    u16 r = (u16)(value % 100u);
    u16 acc = (u16)(q * percent);
    acc = (u16)(acc + (u16)((r * percent) / 100u));
    return acc;
}

1e84aa606b6c3238f699ad933f87a4efcdbe4cd9.source:
static s16 BgmClampS16(s16 value, s16 lo, s16 hi)
{
    if (value < lo) return lo;
    if (value > hi) return hi;
    return value;
}

b0e376f2f08dd56add96d3bc20b44004d17206f2.source:
static s16 BgmLfoStepWave(u8 wave, s16 cur, s8 *sign, s16 depth)
{
    s16 next;
    if (depth <= 0) {
        return 0;
    }
    switch (wave) {
    case 0:
        next = (s16)(cur + *sign);
        if (next >= depth) {
            next = depth;
            *sign = -1;
        } else if (next <= -depth) {
            next = (s16)-depth;
            *sign = 1;
        }
        return next;
    case 1:
        *sign = (*sign < 0) ? 1 : -1;
        return (s16)(depth * (s16)(*sign));
    case 2:
        next = (s16)(cur + 1);
        if (next > depth) {
            next = (s16)-depth;
        }
        return next;
    case 3:
        if (cur < depth) return (s16)(cur + 1);
        return depth;
    case 4:
        if (cur > -depth) return (s16)(cur - 1);
        return (s16)-depth;
    default:
        return cur;
    }
}

586c9bcbeea1832233bfe5af90d07c08d9c031b9.source:
static u8 BgmLfoTick(u8 on, u8 wave, u8 rate, u8 depth,
                     u8 *hold_counter, u8 *counter, s8 *sign, s16 *delta)
{
    s16 next;
    if (!on || depth == 0 || rate == 0) {
        if (*delta != 0) {
            *delta = 0;
            return 1;
        }
        return 0;
    }
    if (*hold_counter > 0) {
        (*hold_counter)--;
        if (*delta != 0) {
            *delta = 0;
            return 1;
        }
        return 0;
    }
    if (*counter == 0) {
        *counter = rate;
        next = BgmLfoStepWave((u8)(wave > 4 ? 4 : wave), *delta, sign, (s16)depth);
        if (next != *delta) {
            *delta = next;
            return 1;
        }
    } else {
        (*counter)--;
    }
    return 0;
}

f1e549ca6dc024d91dd4f000ba81e4deda8fddfc.source:
static s8 BgmLfoToAttnDelta(s16 mod)
{
    s16 d = (s16)(mod / 16);
    if (d < -15) d = -15;
    if (d > 15) d = 15;
    return (s8)(-d);
}

9584ddcd35d7c4b8fb68adb7c275632ac57db5fa.source:
static void BgmLfoResolve(BgmVoice *v)
{
    s16 l1 = v->lfo_delta;
    s16 l2 = v->lfo2_delta;
    s16 mix = (s16)(l1 + l2);
    mix = BgmClampS16(mix, -255, 255);
    switch (v->lfo_algo & 0x07) {
    default:
    case 0:
        v->lfo_pitch_delta = 0;
        v->lfo_attn_delta = 0;
        break;
    case 1:
        v->lfo_pitch_delta = l2;
        v->lfo_attn_delta = BgmLfoToAttnDelta(l1);
        break;
    case 2:
        v->lfo_pitch_delta = mix;
        v->lfo_attn_delta = BgmLfoToAttnDelta(mix);
        break;
    case 3:
        v->lfo_pitch_delta = l2;
        v->lfo_attn_delta = BgmLfoToAttnDelta(mix);
        break;
    case 4:
        v->lfo_pitch_delta = mix;
        v->lfo_attn_delta = BgmLfoToAttnDelta(l1);
        break;
    case 5:
        v->lfo_pitch_delta = 0;
        v->lfo_attn_delta = BgmLfoToAttnDelta(mix);
        break;
    case 6:
        v->lfo_pitch_delta = mix;
        v->lfo_attn_delta = 0;
        break;
    case 7:
        v->lfo_pitch_delta = (s16)(mix / 2);
        v->lfo_attn_delta = 0;
        break;
    }
}

118f6eb6b6efbb23e1a7d546f0ceef4944d5ba50.source:
static u8 BgmVoice_UpdateFx(BgmVoice *v)
{
    u8 dirty = 0;
    if (!v->note_active) {
        return 0;
    }
    if (BgmVoice_MacroTick(v)) {
        dirty = 1;
    }
    if (v->adsr_on && v->adsr_phase > 0) {
        switch (v->adsr_phase) {
        case 1:
            if (v->adsr_attack == 0) {
                v->attn_cur = v->attn;
                v->adsr_phase = 2;
                v->adsr_counter = v->adsr_decay;
                dirty = 1;
            } else if (v->adsr_counter == 0) {
                if (v->attn_cur > v->attn) {
                    v->attn_cur--;
                    dirty = 1;
                }
                if (v->attn_cur <= v->attn) {
                    v->attn_cur = v->attn;
                    v->adsr_phase = 2;
                    v->adsr_counter = v->adsr_decay;
                } else {
                    v->adsr_counter = v->adsr_attack;
                }
            } else {
                v->adsr_counter--;
            }
            break;
        case 2:
        {
            u8 sus_target = v->adsr_sustain;
            if (sus_target < v->attn) sus_target = v->attn;
            if (v->adsr_decay == 0 || sus_target <= v->attn) {
                v->attn_cur = sus_target;
                v->adsr_phase = 3;
                v->adsr_counter = v->adsr_sustain_rate;
                dirty = 1;
            } else if (v->adsr_counter == 0) {
                if (v->attn_cur < sus_target) {
                    v->attn_cur++;
                    dirty = 1;
                }
                if (v->attn_cur >= sus_target) {
                    v->attn_cur = sus_target;
                    v->adsr_phase = 3;
                    v->adsr_counter = v->adsr_sustain_rate;
                } else {
                    v->adsr_counter = v->adsr_decay;
                }
            } else {
                v->adsr_counter--;
            }
            break;
        }
        case 3:
            if (v->adsr_sustain_rate > 0) {
                if (v->adsr_counter == 0) {
                    if (v->attn_cur < 15) {
                        v->attn_cur++;
                        dirty = 1;
                    }
                    if (v->attn_cur >= 15) {
                        v->note_active = 0;
                        v->adsr_phase = 0;
                    } else {
                        v->adsr_counter = v->adsr_sustain_rate;
                    }
                } else {
                    v->adsr_counter--;
                }
            }
            break;
        case 4:
            if (v->adsr_release == 0) {
                v->attn_cur = 15;
                v->adsr_phase = 0;
                v->note_active = 0;
                dirty = 1;
            } else if (v->adsr_counter == 0) {
                if (v->attn_cur < 15) {
                    v->attn_cur++;
                    dirty = 1;
                }
                if (v->attn_cur >= 15) {
                    v->adsr_phase = 0;
                    v->note_active = 0;
                } else {
                    v->adsr_counter = v->adsr_release;
                }
            } else {
                v->adsr_counter--;
            }
            break;
        }
        goto skip_legacy_env;
    }
    if (!v->env_on &&
        !(v->mode == 0 &&
          (v->sweep_on || v->vib_on ||
           (v->lfo_on && v->lfo_depth > 0) ||
           (v->lfo2_on && v->lfo2_depth > 0))) &&
        !dirty) {
        return 0;
    }
    if (v->env_on) {
        if (v->env_counter == 0) {
            if (v->attn_cur < 15) {
                u8 next_attn = (u8)(v->attn_cur + v->env_step);
                if (next_attn > 15) next_attn = 15;
                v->attn_cur = next_attn;
                dirty = 1;
            }
            v->env_counter = v->env_speed;
        } else {
            v->env_counter--;
        }
    }
skip_legacy_env:
    if (v->mode == 0 && v->sweep_on && v->sweep_step != 0) {
        if (v->sweep_counter == 0) {
            s32 nd = (s32)v->tone_div + (s32)v->sweep_step;
            if (nd < 1) nd = 1;
            if (nd > 1023) nd = 1023;
            v->tone_div = (u16)nd;
            v->sweep_counter = v->sweep_speed;
            dirty = 1;
            if (v->sweep_step > 0) {
                if (v->tone_div >= v->sweep_end) v->sweep_on = 0;
            } else {
                if (v->tone_div <= v->sweep_end) v->sweep_on = 0;
            }
        } else {
            v->sweep_counter--;
        }
    }
    if (v->mode == 0 && v->vib_on && v->vib_depth > 0) {
        if (v->vib_delay_counter > 0) {
            v->vib_delay_counter--;
            if (v->vib_delay_counter == 0) {
                v->vib_counter = v->vib_speed;
                v->vib_dir = 1;
                dirty = 1;
            }
        } else {
            if (v->vib_counter == 0) {
                v->vib_dir = (v->vib_dir < 0) ? 1 : -1;
                v->vib_counter = v->vib_speed;
                dirty = 1;
            } else {
                v->vib_counter--;
            }
        }
    }
    if (v->mode == 0) {
        u8 lfo_dirty = 0;
        s16 prev_pitch = v->lfo_pitch_delta;
        s8 prev_attn = v->lfo_attn_delta;
        if (BgmLfoTick(v->lfo_on, v->lfo_wave, v->lfo_rate, v->lfo_depth,
                       &v->lfo_hold_counter, &v->lfo_counter, &v->lfo_sign, &v->lfo_delta)) {
            lfo_dirty = 1;
        }
        if (BgmLfoTick(v->lfo2_on, v->lfo2_wave, v->lfo2_rate, v->lfo2_depth,
                       &v->lfo2_hold_counter, &v->lfo2_counter, &v->lfo2_sign, &v->lfo2_delta)) {
            lfo_dirty = 1;
        }
        BgmLfoResolve(v);
        if (v->lfo_pitch_delta != prev_pitch || v->lfo_attn_delta != prev_attn) {
            lfo_dirty = 1;
        }
        if (lfo_dirty) {
            dirty = 1;
        }
    } else if (v->lfo_pitch_delta != 0 || v->lfo_attn_delta != 0) {
        v->lfo_pitch_delta = 0;
        v->lfo_attn_delta = 0;
        dirty = 1;
    }
    return dirty;
}

af3ad4eb9bacd6aa0b26c957377e0ca7f682f623.source:
static void BgmVoice_Step(BgmVoice *v, PsgCmd *cmd)
{
    u16 scaled;
    u32 song_frame = s_bgm_song_frame;
    cmd->valid = 0;
    if (!v->enabled || !v->ptr) {
        return;
    }
    if (v->gate_active && v->note_active && song_frame >= v->gate_off_frame) {
        BgmVoice_CommandSilence(v, cmd);
        return;
    }
    if (song_frame < v->next_frame) {
        if (BgmVoice_UpdateFx(v)) {
            BgmVoice_CommandFromState(v, cmd);
        }
        return;
    }
    while (v->enabled && song_frame >= v->next_frame) {
        u8 note = *v->ptr++;
        if (note == 0x00) {
            if (s_bgm_loop && (v->loop || v->start)) {
                v->ptr = v->loop ? v->loop : v->start;
                if (v->ptr && *v->ptr != 0x00) {
                    continue;
                }
                BgmVoice_CommandSilence(v, cmd);
                v->next_frame = song_frame + 1;
                return;
            }
            BgmVoice_CommandSilence(v, cmd);
            BgmVoice_Stop(v);
            return;
        }
        if (note == 0xFF) {
            scaled = (u16)(*v->ptr++) * (u16)s_bgm_speed;
            if (scaled == 0) {
                scaled = 1;
            }
            v->next_frame += scaled;
            if (v->adsr_on && v->adsr_release > 0 && v->note_active) {
                v->adsr_phase = 4;
                v->adsr_counter = v->adsr_release;
                BgmVoice_CommandFromState(v, cmd);
            } else {
                BgmVoice_CommandSilence(v, cmd);
            }
            return;
        }
        if (note >= 0xF0) {
            switch (note) {
            case 0xF0: {
                u8 attn = *v->ptr++;
                if (attn > 15) attn = 15;
                v->attn = attn;
                break;
            }
            case 0xF1: {
                u8 step = *v->ptr++;
                u8 speed = *v->ptr++;
                if (step > 4) step = 4;
                if (speed < 1) speed = 1;
                if (speed > 10) speed = 10;
                v->env_on = (step > 0) ? 1 : 0;
                v->env_step = step ? step : 1;
                v->env_speed = speed;
                v->env_counter = v->env_speed;
                v->env_index = 0;
                break;
            }
            case 0xF2: {
                u8 depth = *v->ptr++;
                u8 speed = *v->ptr++;
                u8 delay = *v->ptr++;
                if (speed < 1) speed = 1;
                if (speed > 30) speed = 30;
                v->vib_on = (depth > 0) ? 1 : 0;
                v->vib_depth = depth;
                v->vib_speed = speed;
                v->vib_delay = delay;
                v->vib_delay_counter = v->vib_delay;
                v->vib_counter = v->vib_speed;
                v->vib_dir = 1;
                break;
            }
            case 0xF3: {
                u16 end = (u16)v->ptr[0] | ((u16)v->ptr[1] << 8);
                s8 step = (s8)v->ptr[2];
                u8 speed = v->ptr[3];
                v->ptr += 4;
                if (speed < 1) speed = 1;
                if (speed > 30) speed = 30;
                if (end < 1) end = 1;
                if (end > 1023) end = 1023;
                v->sweep_on = (step != 0) ? 1 : 0;
                v->sweep_end = end;
                v->sweep_step = (s16)step;
                v->sweep_speed = speed;
                v->sweep_counter = v->sweep_speed;
                break;
            }
            case 0xF4:
            {
                u8 inst_id = *v->ptr++;
                BgmVoice_ApplyInstrument(v, inst_id);
                break;
            }
            case 0xF5:
            {
                (void)(*v->ptr++);
                break;
            }
            case 0xF6:
            {
                u8 type = *v->ptr++;
                u8 data = *v->ptr++;
                if (type == 0) {
                    s_bgm_fade_speed = data;
                    s_bgm_fade_counter = data;
                } else if (type == 1) {
                    if (data < 1) data = 1;
                    s_bgm_speed = data;
                }
                break;
            }
            case 0xF7:
            {
                u8 expr = *v->ptr++;
                if (expr > 15) expr = 15;
                v->expression = expr;
                break;
            }
            case 0xF8:
            {
                u8 lo = *v->ptr++;
                u8 hi = *v->ptr++;
                v->pitch_bend = (s16)((u16)lo | ((u16)hi << 8));
                break;
            }
            case 0xF9:
            {
                u8 a = *v->ptr++;
                u8 d = *v->ptr++;
                u8 s = *v->ptr++;
                u8 r = *v->ptr++;
                v->adsr_on = 1;
                v->adsr_attack = a;
                v->adsr_decay = d;
                v->adsr_sustain = s > 15 ? 15 : s;
                v->adsr_sustain_rate = 0;
                v->adsr_release = r;
                v->adsr_phase = 0;
                v->adsr_counter = 0;
                break;
            }
            case 0xFA:
            {
                u8 wave = *v->ptr++;
                u8 rate = *v->ptr++;
                u8 depth = *v->ptr++;
                v->lfo_on = (depth > 0 && rate > 0) ? 1 : 0;
                v->lfo_wave = wave > 4 ? 4 : wave;
                v->lfo_hold = 0;
                v->lfo_rate = rate;
                v->lfo_depth = depth;
                v->lfo_hold_counter = 0;
                v->lfo_counter = rate;
                v->lfo_sign = 1;
                v->lfo_delta = 0;
                v->lfo2_on = 0;
                v->lfo2_delta = 0;
                v->lfo_pitch_delta = 0;
                v->lfo_attn_delta = 0;
                v->lfo_algo = 1;
                break;
            }
            case 0xFE:
            {
                u8 sub = *v->ptr++;
                if (sub == 0x01) {
                    u8 a = *v->ptr++;
                    u8 d = *v->ptr++;
                    u8 sl = *v->ptr++;
                    u8 sr = *v->ptr++;
                    u8 rr = *v->ptr++;
                    v->adsr_on = 1;
                    v->adsr_attack = a;
                    v->adsr_decay = d;
                    v->adsr_sustain = sl > 15 ? 15 : sl;
                    v->adsr_sustain_rate = sr;
                    v->adsr_release = rr;
                    v->adsr_phase = 0;
                    v->adsr_counter = 0;
                } else if (sub == 0x02) {
                    v->lfo_algo = (u8)(*v->ptr++ & 0x07);
                    v->lfo_on = *v->ptr++ ? 1 : 0;
                    v->lfo_wave = (u8)(*v->ptr++ & 0x07);
                    if (v->lfo_wave > 4) v->lfo_wave = 4;
                    v->lfo_hold = *v->ptr++;
                    v->lfo_rate = *v->ptr++;
                    v->lfo_depth = *v->ptr++;
                    v->lfo2_on = *v->ptr++ ? 1 : 0;
                    v->lfo2_wave = (u8)(*v->ptr++ & 0x07);
                    if (v->lfo2_wave > 4) v->lfo2_wave = 4;
                    v->lfo2_hold = *v->ptr++;
                    v->lfo2_rate = *v->ptr++;
                    v->lfo2_depth = *v->ptr++;
                    v->lfo_hold_counter = v->lfo_hold;
                    v->lfo_counter = v->lfo_rate;
                    v->lfo_sign = 1;
                    v->lfo_delta = 0;
                    v->lfo2_hold_counter = v->lfo2_hold;
                    v->lfo2_counter = v->lfo2_rate;
                    v->lfo2_sign = 1;
                    v->lfo2_delta = 0;
                    v->lfo_pitch_delta = 0;
                    v->lfo_attn_delta = 0;
                    if (v->lfo_depth == 0 || v->lfo_rate == 0) v->lfo_on = 0;
                    if (v->lfo2_depth == 0 || v->lfo2_rate == 0) v->lfo2_on = 0;
                } else {
                    v->ptr++;
                }
                break;
            }
            case 0xFB:
            {
                u8 curve_id = *v->ptr++;
                (void)curve_id;
                break;
            }
            case 0xFC:
            {
                u8 curve_id = *v->ptr++;
                (void)curve_id;
                break;
            }
            case 0xFD:
            {
                u8 mid = *v->ptr++;
                (void)mid;
                break;
            }
            default:
                v->ptr++;
                break;
            }
            continue;
        }
        scaled = (u16)(*v->ptr++) * (u16)s_bgm_speed;
        if (scaled == 0) {
            scaled = 1;
        }
        v->next_frame += scaled;
        if (note > 50 + 1) {
            BgmVoice_CommandSilence(v, cmd);
            return;
        }
        BgmVoice_SetNote(v, note);
        if (s_bgm_gate_percent < 100) {
            u16 gate_frames = BgmMulDiv100(scaled, s_bgm_gate_percent);
            if (gate_frames < 1) gate_frames = 1;
            if (gate_frames >= scaled) {
                v->gate_active = 0;
            } else {
                v->gate_active = 1;
                v->gate_off_frame = song_frame + (u32)gate_frames;
            }
        } else {
            v->gate_active = 0;
        }
        BgmVoice_CommandFromState(v, cmd);
        return;
    }
}

132100c3e6e98358181722f125d631f3a8f14bce.source:
static void Sounds_ResetState(void)
{
    u16 i;
    (*(volatile u8 *)0x7003) = 0;
    s_sound_drops = 0;
    s_sound_fault = 0;
    s_sound_last_sfx = 0xFF;
    s_freq_base[0] = 0x80;
    s_freq_base[1] = 0xA0;
    s_freq_base[2] = 0xC0;
    s_freq_base[3] = 0xE0;
    s_attn_base[0] = 0x90;
    s_attn_base[1] = 0xB0;
    s_attn_base[2] = 0xD0;
    s_attn_base[3] = 0xF0;
    s_sfxTimer[0] = 0;
    s_sfxTimer[1] = 0;
    s_sfxTimer[2] = 0;
    s_sfxTimer[3] = 0;
    s_sfx_cmd[0].valid = 0;
    s_sfx_cmd[1].valid = 0;
    s_sfx_cmd[2].valid = 0;
    s_sfx_cmd[3].valid = 0;
    for (i = 0; i < 4; i++) {
        s_psg_shadow[i].valid = 0;
        s_psg_shadow[i].b1 = (u8)(s_attn_base[i] | 0x0F);
        s_psg_shadow[i].b2 = (u8)(s_attn_base[i] | 0x0F);
        s_psg_shadow[i].b3 = (u8)(s_attn_base[i] | 0x0F);
        s_psg_pending[i].valid = 0;
        s_psg_pending[i].b1 = s_psg_shadow[i].b1;
        s_psg_pending[i].b2 = s_psg_shadow[i].b2;
        s_psg_pending[i].b3 = s_psg_shadow[i].b3;
    }
    s_psg_pending_mask = 0;
    s_psg_commit_mask = 0;
    s_sfx_end_pending[0] = 0;
    s_sfx_end_pending[1] = 0;
    s_sfx_end_pending[2] = 0;
    s_sfx_end_pending[3] = 0;
    for (i = 0; i < 3; i++) {
        s_sfx_tone_div_base[i] = 1;
        s_sfx_tone_div_cur[i] = 1;
        s_sfx_tone_attn_base[i] = 15;
        s_sfx_tone_attn_cur[i] = 15;
        s_sfx_tone_sw_end[i] = 1;
        s_sfx_tone_sw_step[i] = 0;
        s_sfx_tone_sw_dir[i] = 1;
        s_sfx_tone_sw_speed[i] = 1;
        s_sfx_tone_sw_counter[i] = 0;
        s_sfx_tone_sw_on[i] = 0;
        s_sfx_tone_sw_ping[i] = 0;
        s_sfx_tone_env_on[i] = 0;
        s_sfx_tone_env_step[i] = 1;
        s_sfx_tone_env_spd[i] = 1;
        s_sfx_tone_env_counter[i] = 0;
    }
    s_sfx_noise_val = 0;
    s_sfx_noise_attn_base = 15;
    s_sfx_noise_attn_cur = 15;
    s_sfx_noise_env_on = 0;
    s_sfx_noise_env_step = 1;
    s_sfx_noise_env_spd = 1;
    s_sfx_noise_env_counter = 0;
    s_sfx_noise_burst = 0;
    s_sfx_noise_burst_dur = 0;
    s_sfx_noise_burst_counter = 0;
    s_sfx_noise_burst_off = 0;
    s_sfx_active_mask = 0;
    s_bgm_note_table = NOTE_TABLE;
    s_bgm_v0.freq_base = 0x80;
    s_bgm_v0.attn_base = 0x90;
    BgmVoice_Reset(&s_bgm_v0);
    s_bgm_v1.freq_base = 0xA0;
    s_bgm_v1.attn_base = 0xB0;
    BgmVoice_Reset(&s_bgm_v1);
    s_bgm_v2.freq_base = 0xC0;
    s_bgm_v2.attn_base = 0xD0;
    BgmVoice_Reset(&s_bgm_v2);
    s_bgm_vn.freq_base = 0xE0;
    s_bgm_vn.attn_base = 0xF0;
    BgmVoice_Reset(&s_bgm_vn);
    s_bgm_vn.inst_id = 1;
    BgmVoice_ApplyInstrument(&s_bgm_vn, s_bgm_vn.inst_id);
    s_bgm_loop = 0;
    s_bgm_speed = 1;
    s_bgm_gate_percent = 100;
    s_bgm_fade_speed = 0;
