static u8 Ngc_BgmDivider(BgmVoice *v, u8 lo, u8 hi)
{
    u16 divider = (u16)lo | ((u16)hi << 8);
    if (v->mode != 0 || divider < 1 || divider > 1023) {
        s_sound_fault = 1;
        return 0;
    }
    v->base_div = divider;
    v->tone_div = divider;
    return 1;
}

