                v->adsr_sustain = s > 15 ? 15 : s;
                v->adsr_sustain_rate = 0;
                v->adsr_release = r;
                v->adsr_phase = 0;
                v->adsr_counter = 0;
                break;
            }
            case 0xFA:
            {
                u8 wave = *v->ptr++;
                u8 rate = *v->ptr++;
                u8 depth = *v->ptr++;
                v->lfo_on = (depth > 0 && rate > 0) ? 1 : 0;
                v->lfo_wave = wave > 4 ? 4 : wave;
                v->lfo_hold = 0;
                v->lfo_rate = rate;
                v->lfo_depth = depth;
                v->lfo_hold_counter = 0;
                v->lfo_counter = rate;
                v->lfo_sign = 1;
                v->lfo_delta = 0;
                v->lfo2_on = 0;
                v->lfo2_delta = 0;
                v->lfo_pitch_delta = 0;
                v->lfo_attn_delta = 0;
                v->lfo_algo = 1;
                break;
            }
            case 0xFE:
            {
                u8 sub = *v->ptr++;
                if (sub == 0x01) {
                    u8 a = *v->ptr++;
                    u8 d = *v->ptr++;
                    u8 sl = *v->ptr++;
                    u8 sr = *v->ptr++;
                    u8 rr = *v->ptr++;
                    v->adsr_on = 1;
                    v->adsr_attack = a;
                    v->adsr_decay = d;
                    v->adsr_sustain = sl > 15 ? 15 : sl;
                    v->adsr_sustain_rate = sr;
                    v->adsr_release = rr;
                    v->adsr_phase = 0;
                    v->adsr_counter = 0;
                } else if (sub == 0x02) {
                    v->lfo_algo = (u8)(*v->ptr++ & 0x07);
                    v->lfo_on = *v->ptr++ ? 1 : 0;
                    v->lfo_wave = (u8)(*v->ptr++ & 0x07);
                    if (v->lfo_wave > 4) v->lfo_wave = 4;
                    v->lfo_hold = *v->ptr++;
                    v->lfo_rate = *v->ptr++;
                    v->lfo_depth = *v->ptr++;
                    v->lfo2_on = *v->ptr++ ? 1 : 0;
                    v->lfo2_wave = (u8)(*v->ptr++ & 0x07);
                    if (v->lfo2_wave > 4) v->lfo2_wave = 4;
                    v->lfo2_hold = *v->ptr++;
                    v->lfo2_rate = *v->ptr++;
                    v->lfo2_depth = *v->ptr++;
                    v->lfo_hold_counter = v->lfo_hold;
                    v->lfo_counter = v->lfo_rate;
                    v->lfo_sign = 1;
                    v->lfo_delta = 0;
                    v->lfo2_hold_counter = v->lfo2_hold;
                    v->lfo2_counter = v->lfo2_rate;
                    v->lfo2_sign = 1;
                    v->lfo2_delta = 0;
                    v->lfo_pitch_delta = 0;
                    v->lfo_attn_delta = 0;
                    if (v->lfo_depth == 0 || v->lfo_rate == 0) v->lfo_on = 0;
                    if (v->lfo2_depth == 0 || v->lfo2_rate == 0) v->lfo2_on = 0;
                } else if (sub == 3) {
                    Ngc_BgmHold(v, cmd, *v->ptr++); return;
                } else if (sub == 4) {
                    if (!Ngc_BgmLevel(v, *v->ptr++)) { BgmVoice_CommandSilence(v, cmd); BgmVoice_Stop(v); return; }
                } else if (sub == 5) {
                    u8 lo = *v->ptr++; u8 hi = *v->ptr++;
                    if (!Ngc_BgmDivider(v, lo, hi)) { BgmVoice_CommandSilence(v, cmd); BgmVoice_Stop(v); return; }
                } else if (sub == 6) {
                    if (!Ngc_BgmNoiseNote(v, *v->ptr++)) { BgmVoice_CommandSilence(v, cmd); BgmVoice_Stop(v); return; }
                } else {
                    v->ptr++;
                }
                break;
            }
            case 0xFB:
            {
                u8 curve_id = *v->ptr++;
                v->env_curve_id = curve_id;
                v->env_index = 0;
                break;
            }
            case 0xFC:
            {
                u8 curve_id = *v->ptr++;
                v->pitch_curve_id = curve_id;
                v->pitch_index = 0;
                v->pitch_counter = v->env_speed;
                v->pitch_offset = 0;
                break;
            }
            case 0xFD:
            {
                u8 mid = *v->ptr++;
                (void)mid;
                break;
            }
            default:
                v->ptr++;
                break;
            }
            continue;
        }
        scaled = (u16)(*v->ptr++) * (u16)s_bgm_speed;
        if (scaled == 0) {
            scaled = 1;
        }
        v->next_frame += scaled;
        if (note > 50 + 1) {
            BgmVoice_CommandSilence(v, cmd);
            return;
        }
        BgmVoice_SetNote(v, note);
        if (s_bgm_gate_percent < 100) {
            u16 gate_frames = BgmMulDiv100(scaled, s_bgm_gate_percent);
            if (gate_frames < 1) gate_frames = 1;
            if (gate_frames >= scaled) {
                v->gate_active = 0;
            } else {
                v->gate_active = 1;
                v->gate_off_frame = song_frame + (u32)gate_frames;
            }
        } else {
            v->gate_active = 0;
        }
        BgmVoice_CommandFromState(v, cmd);
        return;
    }
}

