                v->env_on = (step > 0) ? 1 : 0;
                v->env_step = step ? step : 1;
                v->env_speed = speed;
                v->env_counter = v->env_speed;
                v->env_index = 0;
                v->pitch_index = 0;
                v->pitch_counter = v->env_speed;
                v->pitch_offset = 0;
                break;
